<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
$user=require_login(['office_staff']);$officeId=(int)$user['office_id'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();
 $visitDate=(string)($_POST['visit_date']??'');$clientNumber=trim((string)($_POST['client_number']??''));$surname=trim((string)($_POST['surname']??''));$givenName=trim((string)($_POST['given_name']??''));$middleInitial=mb_strtoupper(mb_substr(trim((string)($_POST['middle_initial']??'')),0,1));$sex=trim((string)($_POST['sex']??''));$age=(int)($_POST['age']??0);$clientType=trim((string)($_POST['client_type']??''));$service=trim((string)($_POST['service_received']??''));$comment=trim((string)($_POST['comment']??''));$ratings=[$_POST['timeliness']??null,$_POST['client_handling']??null,$_POST['quality']??null,$_POST['overall']??null];
 if(!$visitDate||strtotime($visitDate)===false||$visitDate>date('Y-m-d'))$errors[]='Enter a valid service date.';if($clientNumber==='')$errors[]='Enter the client number.';if($surname===''||$givenName==='')$errors[]='Enter the client name.';if(!in_array($sex,['Female','Male','Prefer not to say'],true))$errors[]='Select a valid sex option.';if($age<18||$age>120)$errors[]='Enter a valid adult age from 18 to 120.';if(!in_array($clientType,['Pasigueño','Non-Pasigueño','City Government Employee'],true))$errors[]='Select a valid client type.';if($service==='')$errors[]='Enter the transaction or service received.';if(array_filter($ratings,fn($rating)=>!valid_rating($rating)))$errors[]='Answer all four ratings based on the client’s response.';if(!isset($_POST['client_confirmed']))$errors[]='Confirm that the client personally provided the answers and agreed to this assisted submission.';
 if(!$errors){$record=['visit_date'=>$visitDate,'sex'=>$sex,'age'=>$age,'client_type'=>$clientType,'service'=>$service,'ratings'=>$ratings,'comment'=>$comment];$fingerprint=feedback_fingerprint($officeId,$record);$prediction=feedback_sentiment_prediction($ratings,$comment);$scores=compute_feedback_scores($ratings,$prediction['label']);$reviewStatus=prediction_review_status($prediction);$stmt=db()->prepare("INSERT INTO feedback(office_id,visit_date,sex,age,client_type,service_received,timeliness_rating,client_handling_rating,quality_rating,overall_rating,comment,assisted_by,client_number,surname,given_name,middle_initial,sentiment,original_sentiment,sentiment_confidence,sentiment_source,review_status,model_version,average_rating,rating_percent,comment_score,final_score,source,record_fingerprint,imported_by_user_id,submitted_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?, 'assisted_survey',?,?,NOW())");$stmt->execute([$officeId,$visitDate,$sex,$age,$clientType,$service,(int)$ratings[0],(int)$ratings[1],(int)$ratings[2],(int)$ratings[3],$comment,$user['full_name'],$clientNumber,$surname,$givenName,$middleInitial,$prediction['label'],$prediction['label'],$prediction['confidence'],$prediction['source'],$reviewStatus,model_version(),$scores['average_rating'],$scores['rating_percent'],$scores['comment_score'],$scores['final_score'],$fingerprint,(int)$user['id']]);$id=(int)db()->lastInsertId();create_action_if_needed($id,$officeId,$prediction['label'],$scores['final_score'],$comment);audit((int)$user['id'],'assisted_survey_submit','Submitted assisted survey #'.$id.' for client '.$clientNumber);set_flash('success','Client-assisted survey submitted successfully.');redirect('office/assisted-survey.php');}
}
render_dashboard_start('Assisted Client Survey','assisted_survey');page_header('Assisted Client Survey','Enter the client’s own answers when staff assistance is needed. Client details will auto-fill after the spreadsheet connection is configured.');
?>
<?php if($errors):?><div class="error-box"><?= implode('<br>',array_map('e',$errors)) ?></div><?php endif;?><section class="panel-form"><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="form-row"><div class="form-group"><label>Client Number</label><input name="client_number" value="<?= e($_POST['client_number']??'') ?>" required><div class="help">Automatic lookup will be enabled after Google Sheets API setup.</div></div><div class="form-group"><label>Date of Service</label><input type="date" name="visit_date" value="<?= e($_POST['visit_date']??date('Y-m-d')) ?>" max="<?= e(date('Y-m-d')) ?>" required></div></div><div class="form-row three"><div class="form-group"><label>Surname</label><input name="surname" value="<?= e($_POST['surname']??'') ?>" required></div><div class="form-group"><label>Given Name</label><input name="given_name" value="<?= e($_POST['given_name']??'') ?>" required></div><div class="form-group"><label>Middle Initial</label><input name="middle_initial" maxlength="1" value="<?= e($_POST['middle_initial']??'') ?>"></div></div><div class="form-row three"><div class="form-group"><label>Sex</label><select name="sex" required><option value="">Select</option><?php foreach(['Female','Male','Prefer not to say'] as $value):?><option value="<?= e($value) ?>" <?= ($_POST['sex']??'')===$value?'selected':'' ?>><?= e($value) ?></option><?php endforeach;?></select></div><div class="form-group"><label>Age</label><input type="number" name="age" min="18" max="120" value="<?= e($_POST['age']??'') ?>" required></div><div class="form-group"><label>Client Type</label><select name="client_type" required><option value="">Select</option><?php foreach(['Pasigueño','Non-Pasigueño','City Government Employee'] as $value):?><option value="<?= e($value) ?>" <?= ($_POST['client_type']??'')===$value?'selected':'' ?>><?= e($value) ?></option><?php endforeach;?></select></div></div><div class="form-group"><label>Transaction / Service</label><input name="service_received" value="<?= e($_POST['service_received']??'') ?>" required></div><h2>Client Ratings</h2><p class="muted">Read each item to the client and encode the answer they give.</p><?php $questions=['timeliness'=>'Bilis ng serbisyo','client_handling'=>'Pakikitungo sa kliyente','quality'=>'Kalidad ng serbisyo','overall'=>'Overall satisfaction'];foreach($questions as $name=>$label):?><div class="form-group"><label><?= e($label) ?></label><select name="<?= e($name) ?>" required><option value="">Select rating</option><?php for($i=1;$i<=4;$i++):?><option value="<?= $i ?>" <?= (string)($_POST[$name]??'')===(string)$i?'selected':'' ?>><?= $i ?> — <?= ['','Strongly Disagree','Disagree','Agree','Strongly Agree'][$i] ?></option><?php endfor;?></select></div><?php endforeach;?><div class="form-group"><label>Comment (Optional)</label><textarea name="comment" maxlength="3000"><?= e($_POST['comment']??'') ?></textarea></div><label class="checkbox-row"><input type="checkbox" name="client_confirmed" value="1" required><span>Kinumpirma ng client na ang mga rating at optional comment ay sariling sagot nila at pumayag silang i-submit ito sa tulong ng staff.</span></label><button class="btn" style="margin-top:16px">Submit Assisted Survey</button></form></section>
